/// <summary>
/// This is the data contract class for the price list ER report
/// </summary>
[DataContractAttribute]
public class AVAERWarehouseArrivalContract extends ERFormatMappingRunBaseContract
{
    CreatedTransactionId createdTransactionId;
    str packedQuery;
    public boolean     printToMemory;

}

Method.Source:
/// <summary>
/// parm method for packedQuery
/// </summary>
/// <param name = "_packedQuery">str</param>
/// <returns>str</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_packedQuery', queryStr(AVAERWarehouseArrival))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

public CreatedTransactionid parmCreatedTransactionId(CreatedTransactionId _createdTransactionId = createdTransactionId)
{
    createdTransactionId = _createdTransactionId;

    return createdTransactionId;
}

public boolean parmPrintToMemory(boolean        _printToMemory = printToMemory)
{
    printToMemory = _printToMemory;
    return printToMemory;
}

// This method unpacks the query and returns it as query object.
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

// This method takes a query object, encodes it and stores the packed query.
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// initFromArgs method
/// </summary>
/// <param name = "_args">Args</param>
public void initFromArgs(Args _args)
{
    FormRun formRun = _args.caller();
    FormDataSource fds_wmsArrivalTmp = formRun.dataSource();
    MultiSelectionHelper helper = MultiSelectionHelper::construct();

    helper.parmDatasource(fds_wmsArrivalTmp);

    //FormDataSource fds_priceList = FormDataUtil::getFormDataSource(_args.record());
    //Query query = this.getQuery();
    Query query = new Query(queryStr(AVAERWarehouseArrival));
    QueryBuildDataSource qbdsWMSArrivalOverviewTmp = query.dataSourceTable(tablenum(AVAWMSArrivalOverviewTmp));
    QueryBuildRange qbrRecId = qbdsWMSArrivalOverviewTmp.addRange(FieldNum(AVAWMSArrivalOverviewTmp, CreatedTransactionId));

    this.parmCreatedTransactionId(formRun.avaParmCreatedTransactionId());
    qbrRecId.value(queryValue(_args.parm()));

    this.setQuery(query);       
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_purchId">PurchId</param>
public void initFromPurchId(PurchId _purchId)
{
    Query query = new Query(queryStr(AVAERWarehouseArrival));
    QueryBuildDataSource qbdsWMSArrivalOverviewTmp = query.dataSourceTable(tablenum(AVAWMSArrivalOverviewTmp));
    QueryBuildRange qbrPurchId = qbdsWMSArrivalOverviewTmp.addRange(FieldNum(AVAWMSArrivalOverviewTmp, InventTransRefId));
    QueryBuildRange qbrInventTransType = qbdsWMSArrivalOverviewTmp.addRange(FieldNum(AVAWMSArrivalOverviewTmp, InventTransType));

    qbrPurchId.value(_purchId);
    qbrInventTransType.value(queryValue(InventTransType::Purch));

    this.setQuery(query);
}
